export function ApplyButton({
  label = "{{label}}",
  count = {{count}},
  bg = "{{bg}}",
  radius = {{radius}},
  disabled = {{disabled}},
}) {
  return (
    <button
      type="button"
      disabled={disabled}
      style={{
        display: "inline-flex",
        alignItems: "center",
        gap: 8,
        padding: "11px 20px",
        border: "none",
        borderRadius: radius,
        background: bg,
        color: "#FAF7F2",
        font: "600 15px/1 system-ui, sans-serif",
        cursor: disabled ? "not-allowed" : "pointer",
        opacity: disabled ? 0.45 : 1,
      }}
    >
      {label}
      {count > 0 && (
        <span
          style={{
            display: "inline-flex",
            alignItems: "center",
            justifyContent: "center",
            minWidth: 18,
            height: 18,
            padding: "0 5px",
            borderRadius: 999,
            background: "#FAF7F2",
            color: bg,
            font: "700 11px/1 system-ui, sans-serif",
          }}
        >
          {count}
        </span>
      )}
    </button>
  );
}
